$registros=$rol==='docente'?$m->obtenerParaDocente($idUsuario):$m->obtenerTodas();
if($rol==='estudiante'){ $s=$pdo->prepare('SELECT e.id_estudiante FROM estudiantes e WHERE e.id_usuario=?');$s->execute([$idUsuario]);$eid=$s->fetchColumn();$q=$pdo->prepare("SELECT c.*,CONCAT(u.nombre,' ',u.apellido) estudiante,cu.nombre_curso,cu.codigo FROM calificaciones c JOIN inscripciones i ON i.id_inscripcion=c.id_inscripcion JOIN estudiantes e ON e.id_estudiante=i.id_estudiante JOIN usuarios u ON u.id_usuario=e.id_usuario JOIN cursos cu ON cu.id_curso=i.id_curso WHERE e.id_estudiante=? ORDER BY c.fecha DESC");$q->execute([$eid]);$registros=$q->fetchAll();$accion=$accion==='ver'?'ver':'listar';}
